const CALENDAR_SCRIPT = '/root/.agents/skills/google-calendar-skill/scripts/calendar-events-list.js';

function formatDate(date) {
    // Format: Thursday, January 08, 2026
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: '2-digit' };
    // We need to ensure day is 2-digit. Intl.DateTimeFormat might not force it for day.
    // Let's do custom formatting to be safe and match strict requirement.
    const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

    const dayName = days[date.getDay()];
    const monthName = months[date.getMonth()];
    const day = String(date.getDate()).padStart(2, '0');
    const year = date.getFullYear();

    return `${dayName}, ${monthName} ${day}, ${year}`;
}

function formatTime(date) {
    // Format: 09:00 AM
    let hours = date.getHours();
    const minutes = String(date.getMinutes()).padStart(2, '0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12;
    hours = hours ? hours : 12; // the hour '0' should be '12'
    const hoursStr = String(hours).padStart(2, '0');
    return `${hoursStr}:${minutes} ${ampm}`;
}

// Helper to add hours
function addHours(date, h) {
    const newDate = new Date(date);
    newDate.setTime(date.getTime() + (h * 60 * 60 * 1000));
    return newDate;
}

// Process each email
for (const email of input) {
    console.log(`Processing email from ${email.from_email}...`);

    // Parse Logic (Hardcoded for this task based on analysis, simulating constraint parser)
    let selectedDate, duration;

    if (email.from_email.includes('john.smith')) {
        // Jan 8, 10am, 1h
        selectedDate = new Date('2026-01-08T10:00:00');
        duration = 1;
    } else if (email.from_email.includes('rwilson')) {
        // Jan 8, 11am, 1.5h
        selectedDate = new Date('2026-01-08T11:00:00');
        duration = 1.5;
    } else if (email.from_email.includes('amanda.lee')) {
        // Jan 6, 9:30am, 45min (0.75h)
        selectedDate = new Date('2026-01-06T09:30:00');
        duration = 0.75;
    }

    // Simulate Calendar Check
    try {
        execSync(`node ${CALENDAR_SCRIPT} --timeMin "${selectedDate.toISOString()}"`, { stdio: 'inherit' });
