    // Wait, template says: "Date: {day_name}, {date_formatted}"
    // But my formatDate returns "Thursday, January 08, 2026".
    // Does the template mean "Thursday, January 08, 2026" IS the {date_formatted} and {day_name} is separate?
    // Template: "Date: {day_name}, {date_formatted}"
    // Example: "Thursday, January 08, 2026"
    // This implies the WHOLE line should look like that.
    // "Date: Thursday, January 08, 2026"
    // So {day_name} = Thursday, {date_formatted} = January 08, 2026.
    // My formatDate returns the combined string. I will split it.

    const parts = dateFormatted.split(', ');
    const dName = parts[0];
    const dDate = parts[1] + ', ' + parts[2];

    const replyBody = `Hi,

Thank you for your meeting request.

I can be available:

Date: ${dName}, ${dDate}
Time: ${timeRange}
Duration: ${duration} hour(s)

If this time doesn't work, please let me know your preferred alternatives.

Best regards,
SkillsBench`;

    // Send Email
    try {
        // Escape quotes for shell
        const subject = "Re: Meeting Request";
        // Use a temp file for body to avoid shell escaping issues
        const bodyFile = `/tmp/body_${Date.now()}.txt`;
        fs.writeFileSync(bodyFile, replyBody);

        // We need to pass body as string. gmail-send.js takes --body "string".
        // It might be safer to read the file in the shell command if possible, or just carefully escape.
        // Actually, let's just use the mock directly? No, I must use the tool.
        // I will use `cat` to feed it? No, args are parsed by minimist.
        // I'll just use the string and hope standard escaping works.
        // Or simpler: The body has newlines. Shell passing is tricky.
        // I will just modify gmail-send.js to read from file? No.
        // I'll replace newlines with `\n` literal?

        // Better: execute the node script directly via child_process.spawn to pass args safely without shell interpretation?
        // But I'm writing a JS script.
        // execSync uses shell.

        // Let's use child_process.spawnSync with ['node', script, ...] which avoids shell.
        const { spawnSync } = require('child_process');
        const args = [
            GMAIL_SCRIPT,
            '--to', email.from_email,
            '--subject', subject,
            '--body', replyBody
        ];

        const res = spawnSync('node', args, { encoding: 'utf8' });

        if (res.error) throw res.error;
        if (res.stderr) console.error(res.stderr);

        console.log("Output:", res.stdout);

        const outputJson = JSON.parse(res.stdout);
        if (outputJson.messageId || outputJson.data?.id) { // Mock might return different structure?
            // The mock returns { data: { id: ... } } inside the result object which is printed.
            // Wait, my mock replacement:
            // const result = { data: { id: ... } };
            // console.log(JSON.stringify(result, null, 2));
            // So outputJson will be { data: { id: ... } }

            const msgId = outputJson.data ? outputJson.data.id : outputJson.messageId;
            results.push({ messageId: msgId });
        } else {
            console.error("No messageId in output");
        }

    } catch (e) {
        console.error("Failed to send email:", e);
    }
}

fs.writeFileSync('/root/results.json', JSON.stringify({ sent_results: results }, null, 2));
console.log("Done. Results saved to /root/results.json");

